#!/bin/bash
#SBATCH -J @JOB_NAME@
#SBATCH -A @ACCOUNT@
#SBATCH -q @QOS@
#SBATCH -C cpu
#SBATCH -N 1
#SBATCH --exclusive
#SBATCH -t @TIME@
#SBATCH --array=@YEAR0@-@YEAR1@
#SBATCH -o @LOG_DIR@/mcsenv_@SOURCE@_%A_%a.out
#
# MCS environment extraction of one source, one year per array task and one node per year (generated by gen_mcs_env_jobs.py).
# Each task writes @OUT_DIR@/@SOURCE@/mcs_env_@SOURCE@_<year>.parquet; check it afterwards with
#   python @CODE_DIR@/check_mcs_env_output.py <file> --brute-force 40
# and combine the years with
#   python @CODE_DIR@/combine_mcs_env.py --source @SOURCE@ --years @YEAR0@ @YEAR1@ --dir @OUT_DIR@

# The netCDF library must not lock files on the parallel file systems; every worker is single-threaded
export HDF5_USE_FILE_LOCKING=FALSE
export OMP_NUM_THREADS=1
export OPENBLAS_NUM_THREADS=1

YEAR=${SLURM_ARRAY_TASK_ID}
echo "source @SOURCE@ year ${YEAR} on $(hostname) started $(date)"

# One year with @NPROC@ worker processes (the node has 128 cores)
@PYTHON@ @CODE_DIR@/extract_mcs_env.py --source @SOURCE@ --years ${YEAR} ${YEAR} --nproc @NPROC@ --out-dir @OUT_DIR@
status=$?
echo "finished $(date) with status ${status}"
exit ${status}
